from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/main.py', 'from __future__ import annotations\n\nfrom contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI, Request\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.responses import ORJSONResponse\nfrom prometheus_client import CONTENT_TYPE_LATEST, generate_latest\nfrom starlette.middleware.trustedhost import TrustedHostMiddleware\nfrom starlette.responses import Response\n\nfrom app.api.routes import (\n    backtests,\n    compatibility,\n    datasets,\n    health,\n    models,\n    outcomes,\n    predictions,\n    stations,\n    training,\n)\nfrom app.core.config import get_settings\nfrom app.core.exceptions import ServiceError\nfrom app.core.logging import configure_logging\nfrom app.core.middleware import RequestContextMiddleware, SimpleRateLimitMiddleware\nfrom app.db.base import Base\nfrom app.db.session import engine\n\nconfigure_logging()\nsettings = get_settings()\n\n\n@asynccontextmanager\nasync def lifespan(_: FastAPI):\n    if settings.auto_create_tables:\n        Base.metadata.create_all(bind=engine)\n    yield\n\n\napp = FastAPI(\n    title=settings.app_name,\n    version="1.0.0",\n    description=(\n        "Secure model training, calibrated weather-market probability inference, backtesting, "\n        "model registry, and outcome evaluation for a Kalshi-connected application."\n    ),\n    lifespan=lifespan,\n    default_response_class=ORJSONResponse,\n)\napp.add_middleware(RequestContextMiddleware)\napp.add_middleware(SimpleRateLimitMiddleware)\napp.add_middleware(TrustedHostMiddleware, allowed_hosts=settings.trusted_hosts)\nif settings.cors_origins:\n    app.add_middleware(\n        CORSMiddleware,\n        allow_origins=settings.cors_origins,\n        allow_credentials=False,\n        allow_methods=["GET", "POST", "PUT", "PATCH", "DELETE"],\n        allow_headers=["Content-Type", "X-API-Key", "X-Admin-Key", "X-Request-ID"],\n    )\n\n\n@app.exception_handler(ServiceError)\nasync def service_error_handler(_: Request, exc: ServiceError) -> ORJSONResponse:\n    return ORJSONResponse(status_code=exc.status_code, content={"detail": exc.as_detail()})\n\n\napp.include_router(health.router)\napp.include_router(stations.router, prefix=settings.api_prefix)\napp.include_router(datasets.router, prefix=settings.api_prefix)\napp.include_router(predictions.router, prefix=settings.api_prefix)\napp.include_router(training.router, prefix=settings.api_prefix)\napp.include_router(models.router, prefix=settings.api_prefix)\napp.include_router(backtests.router, prefix=settings.api_prefix)\napp.include_router(outcomes.router, prefix=settings.api_prefix)\napp.include_router(compatibility.router, prefix=settings.api_prefix)\n\n\n@app.get("/metrics", include_in_schema=False)\ndef metrics() -> Response:\n    if not settings.prometheus_enabled:\n        return Response(status_code=404)\n    return Response(generate_latest(), media_type=CONTENT_TYPE_LATEST)\n')
write('app/ml/__init__.py', '')
write('app/ml/artifact_store.py', 'from __future__ import annotations\n\nimport hashlib\nimport io\nfrom pathlib import Path\nfrom urllib.parse import urlparse\n\nimport joblib\n\nfrom app.core.config import get_settings\nfrom app.ml.bundle import ModelBundle\n\n\nclass ArtifactStore:\n    def save_bundle(self, bundle: ModelBundle) -> tuple[str, str]:\n        raise NotImplementedError\n\n    def load_bundle(self, uri: str, expected_sha256: str | None = None) -> ModelBundle:\n        raise NotImplementedError\n\n\nclass LocalArtifactStore(ArtifactStore):\n    def __init__(self, root: Path):\n        self.root = root\n        self.root.mkdir(parents=True, exist_ok=True)\n\n    def save_bundle(self, bundle: ModelBundle) -> tuple[str, str]:\n        target = self.root / f"{bundle.version}.joblib"\n        temporary = target.with_suffix(".tmp")\n        joblib.dump(bundle, temporary, compress=3)\n        temporary.replace(target)\n        digest = hashlib.sha256(target.read_bytes()).hexdigest()\n        return str(target), digest\n\n    def load_bundle(self, uri: str, expected_sha256: str | None = None) -> ModelBundle:\n        path = Path(uri)\n        payload = path.read_bytes()\n        digest = hashlib.sha256(payload).hexdigest()\n        if expected_sha256 and digest != expected_sha256:\n            raise ValueError("Model artifact checksum verification failed.")\n        bundle = joblib.load(io.BytesIO(payload))\n        if not isinstance(bundle, ModelBundle):\n            raise TypeError("Artifact is not a ModelBundle.")\n        return bundle\n\n\nclass S3ArtifactStore(ArtifactStore):\n    def __init__(self, uri: str):\n        import boto3\n\n        settings = get_settings()\n        parsed = urlparse(uri)\n        self.bucket = parsed.netloc\n        self.prefix = parsed.path.strip("/")\n        self.client = boto3.client(\n            "s3",\n            endpoint_url=settings.s3_endpoint_url,\n            region_name=settings.aws_region,\n            aws_access_key_id=settings.aws_access_key_id,\n            aws_secret_access_key=settings.aws_secret_access_key,\n        )\n\n    def _key(self, version: str) -> str:\n        name = f"{version}.joblib"\n        return f"{self.prefix}/{name}" if self.prefix else name\n\n    def save_bundle(self, bundle: ModelBundle) -> tuple[str, str]:\n        buffer = io.BytesIO()\n        joblib.dump(bundle, buffer, compress=3)\n        payload = buffer.getvalue()\n        digest = hashlib.sha256(payload).hexdigest()\n        key = self._key(bundle.version)\n        self.client.put_object(Bucket=self.bucket, Key=key, Body=payload)\n        return f"s3://{self.bucket}/{key}", digest\n\n    def load_bundle(self, uri: str, expected_sha256: str | None = None) -> ModelBundle:\n        parsed = urlparse(uri)\n        response = self.client.get_object(Bucket=parsed.netloc, Key=parsed.path.strip("/"))\n        payload = response["Body"].read()\n        digest = hashlib.sha256(payload).hexdigest()\n        if expected_sha256 and digest != expected_sha256:\n            raise ValueError("Model artifact checksum verification failed.")\n        bundle = joblib.load(io.BytesIO(payload))\n        if not isinstance(bundle, ModelBundle):\n            raise TypeError("Artifact is not a ModelBundle.")\n        return bundle\n\n\ndef get_artifact_store() -> ArtifactStore:\n    settings = get_settings()\n    if settings.model_store_uri.startswith("s3://"):\n        return S3ArtifactStore(settings.model_store_uri)\n    return LocalArtifactStore(settings.model_store_path)\n')
